import gurobipy as gp
from gurobipy import GRB
shelf_records = [r for r in LEGACY_RECORDS if 'resource_id' in r['values'] and 'resource_capacity' in r['values']]
product_records = [r for r in LEGACY_RECORDS if 'item_name' in r['values'] and 'item_value' in r['values'] and ('resource_requirement' in r['values'])]
shelves = [rec['values']['resource_id'] for rec in shelf_records]
products = [rec['values']['item_name'] for rec in product_records]
resource_capacity = {rec['values']['resource_id']: int(rec['values']['resource_capacity']) for rec in shelf_records}
item_value = {rec['values']['item_name']: int(rec['values']['item_value']) for rec in product_records}
resource_requirement = {rec['values']['item_name']: int(rec['values']['resource_requirement']) for rec in product_records}
if set(resource_capacity.keys()) != set(shelves):
    raise ValueError('Mismatch in shelf identifiers and resource_capacity keys')
if set(item_value.keys()) != set(products) or set(resource_requirement.keys()) != set(products):
    raise ValueError('Mismatch in product identifiers and item_value/resource_requirement keys')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[j] * x[i, j] for i in shelves for j in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((resource_requirement[j] * x[i, j] for j in products)) <= resource_capacity[i] for i in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')